insert into sale_payment_channel_order (
    payment_order_no, unique_order_no, merchant_no, order_id, channel_order_id, order_amount, pay_amount, status,
    pay_success_date, channel, payer_info, fail_code, fail_reason, channel_trx_id, bank_order_id, callback_type,
    callback_body, callback_time, created_at, updated_at
) values (
    #{paymentOrderNo}, #{uniqueOrderNo}, #{merchantNo}, #{orderId}, #{channelOrderId}, #{orderAmount}, #{payAmount}, #{status},
    #{paySuccessDate}, #{channel}, #{payerInfo}, #{failCode}, #{failReason}, #{channelTrxId}, #{bankOrderId}, #{callbackType},
    #{callbackBody}, #{callbackTime}, #{createdAt}, #{updatedAt}
)
